  'chat.designToolbox.prompt.autoMatchStep1': '1. δ¿╝∞áÇ ΓÇ£δ│┤Ω╕░ ∞óï∞¥Ç δöö∞₧É∞¥╕ΓÇ¥∞¥┤ δ¼┤∞ùç∞¥╕∞ºÇ ∞áò∞¥ÿφòÿ∞ä╕∞Üö: δîÇ∞âü, δ╣ä∞ªêδïê∞èñ δ¬⌐φæ£, δ╕îδ₧£δô£ δèÉδéî, ∞èñφâÇ∞¥╝ δáêφì╝δƒ░∞èñ, ∞áòδ│┤ δ░ÇδÅä, ∞âë∞âü/φâÇ∞¥┤φÅ¼/δ¬¿∞àÿ/∞ùÉ∞àï Ω╕░∞ñÇ, Ω╖╕δª¼Ω│á φö╝φò┤∞ò╝ φòá AI/φà£φöîδª┐ φî¿φä┤.',
  'chat.designToolbox.prompt.autoMatchStep2': '2. ∞£ä∞¥ÿ ∞áä∞▓┤ δª¼∞åî∞èñ ∞¥╕δì▒∞èñδÑ╝ Ω▓Ç∞âëφòÿΩ│á δºñ∞╣¡φòÿ∞ä╕∞Üö. δöö∞₧É∞¥╕ φê┤δ░ò∞èñ ∞╢ö∞▓£δºî ∞é¼∞Ü⌐φòÿ∞ºÇ δºÉΩ│á, ∞£á∞Ü⌐φòá δòî skill, MCP, φöîδƒ¼Ω╖╕∞¥╕, ∞╗ñδäÑφä░, δöö∞₧É∞¥╕ φîî∞¥╝∞¥ä Ω▓░φò⌐φòÿ∞ä╕∞Üö.',
  'chat.designToolbox.prompt.autoMatchStep3': '3. δîÇ∞âü∞¥┤δéÿ δ»╕∞áü Ω╕░∞ñÇ∞¥┤ ∞òä∞ºü δ╢êδ╢äδ¬àφòÿδ⌐┤, φò£∞áòδÉ£ ∞äáφâ¥∞ºÇδéÿ φÅ╝ φÿòφâ£∞¥ÿ UIδí£ ∞òêδé┤φòÿΩ│á Ω╢î∞₧Ñ Ω╕░δ│╕Ω░Æ∞¥ä φÅ¼φò¿φòÿ∞ä╕∞Üö. ∞╢⌐δ╢äφ₧ê δ¬àφÖòφòÿδ⌐┤ δïñ∞¥î δï¿Ω│äδÑ╝ δ░öδí£ ∞ïñφûëφòÿ∞ä╕∞Üö.',
  'chat.designToolbox.prompt.autoMatchStep4': '4. δïñ∞¥î ∞ê£∞ä£δí£ φöîδí£δÑ╝ ∞Öäδúîφòÿ∞ä╕∞Üö: ∞ºäδï¿ -> ∞èñφâÇ∞¥╝ δ░⌐φûÑ -> δª¼∞åî∞èñ ∞äáφâ¥ -> Ω╡¼∞▓┤∞áü φÄ╕∞ºæ/∞â¥∞ä▒ -> Ω▓Ç∞ª¥. Ω░ü δï¿Ω│ä∞ùÉ∞ä£ ∞¥┤ δª¼∞åî∞èñδÑ╝ ∞äáφâ¥φò£ ∞¥┤∞£á∞ÖÇ δïñ∞¥î∞ùÉ δ¼┤∞ùç∞¥ä φÖò∞¥╕φò┤∞ò╝ φòÿδèö∞ºÇ ∞äñδ¬àφòÿ∞ä╕∞Üö.',
  'chat.designToolbox.prompt.motion': 'φÿä∞₧¼ HTML / φÄÿ∞¥┤∞ºÇ ∞Üö∞åî∞ùÉ Ω│áφÆê∞ºê δ¬¿∞àÿ∞¥ä ∞╢öΩ░Çφòÿ∞ä╕∞Üö: Ω░Ç∞₧Ñ ∞£á∞Ü⌐φò£ ∞ºä∞₧à, ∞èñφü¼δíñ, ∞âüφâ£ ∞áäφÖÿ δÿÉδèö δºê∞¥┤φü¼δí£ ∞¥╕φä░δ₧Ö∞àÿ ∞ê£Ω░ä∞¥ä 1-2Ω░£ ∞äáφâ¥φòÿ∞ä╕∞Üö. ∞áê∞á£δÉ£ φæ£φÿä∞¥ä ∞£á∞ºÇφòÿΩ│á, transform / opacityδÑ╝ ∞Ü░∞äáφòÿδ⌐░, prefers-reduced-motion φÅ┤δ░▒∞¥ä φÅ¼φò¿φòÿ∞ä╕∞Üö.',
  'chat.designToolbox.prompt.motionPolish': 'Ω╕░∞í┤ δ¬¿∞àÿ∞¥ÿ φâÇ∞¥┤δ░ì, ∞¥┤∞ºò, ∞ä▒δèÑ, ∞áæΩ╖╝∞ä▒∞¥ä Ω▓ÇφåáφòÿΩ│á δïñδô¼∞£╝∞ä╕∞Üö. Ω░æ∞₧æ∞èñδƒ╜Ω▒░δéÿ ∞í░∞₧íφòÿΩ▒░δéÿ Ω░ÇδÅà∞ä▒∞¥ä φò┤∞╣ÿδèö ∞òáδïêδ⌐ö∞¥┤∞àÿ∞¥ä ∞á£Ω▒░φòÿΩ│á, φòä∞Üöφòá δòî δìö ∞áòΩ╡Éφò£ φâÇ∞₧äδ¥╝∞¥╕∞¥ä ∞é¼∞Ü⌐φòÿ∞ä╕∞Üö.',
  'chat.designToolbox.prompt.antiAiPolish': 'AI δèÉδéî ∞á£Ω▒░ φÅ┤δª¼∞ï▒∞¥ä φò£ ∞░¿δíÇ ∞êÿφûëφòÿ∞ä╕∞Üö: φïÇ∞ùÉ δ░òφ₧î δáê∞¥┤∞òä∞¢â, ∞í░∞₧íφò£ Ω╖╕δ¥╝δì░∞¥┤∞àÿ/Ω╕Çδí£∞Ü░, ∞¥ÿδ»╕ ∞ùåδèö ∞╣┤δô£ ∞èñφâ¥, δ¬¿φÿ╕φò£ ∞╣┤φö╝δÑ╝ ∞á£Ω▒░φòÿ∞ä╕∞Üö. ∞áòδ│┤δèö ∞£á∞ºÇφòÿΩ│á ∞ïñ∞á£ δöö∞₧É∞¥┤δäêΩ░Ç δºîδôá Ω▓â∞▓ÿδƒ╝ δèÉΩ╗┤∞ºÇΩ▓î φòÿ∞ä╕∞Üö.',
