  'chat.example1Prompt': 'δöö∞₧É∞¥╕ ∞èñφè£δöö∞ÿñ∞¥ÿ ∞ï£δô£ δ¥╝∞Ü┤δô£ φê¼∞₧É ∞£á∞╣ÿδÑ╝ ∞£äφò£ 10∞₧Ñ∞º£δª¼ ∞ùÉδööφåáδª¼∞û╝ φö╝∞╣ÿ δì▒∞¥ä δºîδôñ∞û┤ ∞ú╝∞ä╕∞Üö. ∞èñ∞£ä∞èñ ∞èñφâÇ∞¥╝∞¥ÿ Ω╖╕δª¼δô£ δáê∞¥┤∞òä∞¢â, δ│╝δô£φò£ δô£δí¡ ∞║í∞¥┤ ∞₧êδèö φü¼Ω│á Ω╡╡∞¥Ç ∞ä╕δª¼φöä∞▓┤ φùñδô£δ¥╝∞¥╕, Ω│á∞áòφÅ¡ φÅ░φè╕∞¥ÿ ∞ä╣∞àÿ δ▓êφÿ╕, δäëδäëφò£ ∞ù¼δ░▒, φàì∞èñφè╕Ω░Ç δºÄ∞¥Ç ∞è¼δ¥╝∞¥┤δô£∞ÖÇ δîÇδ╣äδÉÿδèö Ω╜ë ∞░¼ ∞¥┤δ»╕∞ºÇ ∞è¼δ¥╝∞¥┤δô£δÑ╝ ∞í░φò⌐φò┤ ∞ú╝∞ä╕∞Üö. ∞╗ñδ▓ä, δ╣ä∞áä, ∞ï£∞₧Ñ, ∞á£φÆê, φè╕δ₧Ö∞àÿ, φîÇ Ω╡¼∞ä▒, φê¼∞₧É ∞Üö∞▓¡∞òí, ∞ù░δ¥╜∞▓ÿδÑ╝ φÅ¼φò¿φò┤ ∞ú╝∞ä╕∞Üö.',
