  'chat.example2Tag': 'δì░∞¥┤φä░',
  'chat.example2Prompt': 'Ω░£δ░£∞₧É δÅäΩ╡¼ SaaSδÑ╝ ∞£äφò£ ∞áòδ│┤Ω░Ç δ░Ç∞ºæδÉ£ ∞òáδäÉδª¼φï▒∞èñ δîÇ∞ï£δ│┤δô£δÑ╝ δºîδôñ∞û┤ ∞ú╝∞ä╕∞Üö. ∞áä∞ú╝ δîÇδ╣ä δ│ÇφÖöδƒë∞¥ä δ│┤∞ù¼∞ú╝δèö ∞ú╝∞Üö KPI ∞èñφè╕δª╜, δæÉ Ω░£∞¥ÿ δêä∞áü ∞äá Ω╖╕δ₧ÿφöä (MRR δ░Å φÖ£∞ä▒ ∞¢îφü¼∞èñφÄÿ∞¥┤∞èñ), ∞é¼∞Ü⌐δƒë Ω╕░∞ñÇ ∞áä ∞ä╕Ω│ä φ₧êφè╕δº╡, ∞╜öφÿ╕φè╕ δª¼φàÉ∞àÿ Ω╖╕δª¼δô£, ∞âü∞£ä Ω│áΩ░¥ δª¼δìöδ│┤δô£, Ω╖╕δª¼Ω│á ∞ïñ∞ï£Ω░ä ∞¥┤δ▓ñφè╕ φö╝δô£Ω░Ç φÅ¼φò¿δÉÿ∞û┤∞ò╝ φò⌐δïêδïñ. δïñφü¼ φàîδºêδÑ╝ Ω╕░δ░ÿ∞£╝δí£, Ω░ÇδÅà∞ä▒∞¥ä ∞£äφò£ Ω│á∞áòφÅ¡ ∞ê½∞₧ÉδÑ╝ ∞é¼∞Ü⌐φòÿΩ│á ∞èñφîîφü¼δ¥╝∞¥╕ φÅ¼∞¥╕φè╕ ∞âë∞âü∞£╝δí£ Ω░ò∞í░φò┤ ∞ú╝∞ä╕∞Üö.',
